using System;using System.IO;using System.Linq;using System.Threading.Tasks;using System.Collections.Generic;using UnityEngine;using AntColony.Units;
public static class Final1113NearestContact {
 static Vector3[] Read(Mesh m){using(var data=UnityEditor.MeshUtility.AcquireReadOnlyMeshData(m)){using(var a=new Unity.Collections.NativeArray<Vector3>(data[0].vertexCount,Unity.Collections.Allocator.Temp)){data[0].GetVertices(a);return a.ToArray();}}}
 static Vector3 Closest(Vector3 p,Vector3 a,Vector3 b,Vector3 c){var ab=b-a;var ac=c-a;var ap=p-a;float d1=Vector3.Dot(ab,ap),d2=Vector3.Dot(ac,ap);if(d1<=0&&d2<=0)return a;var bp=p-b;float d3=Vector3.Dot(ab,bp),d4=Vector3.Dot(ac,bp);if(d3>=0&&d4<=d3)return b;float vc=d1*d4-d3*d2;if(vc<=0&&d1>=0&&d3<=0)return a+ab*(d1/(d1-d3));var cp=p-c;float d5=Vector3.Dot(ab,cp),d6=Vector3.Dot(ac,cp);if(d6>=0&&d5<=d6)return c;float vb=d5*d2-d1*d6;if(vb<=0&&d2>=0&&d6<=0)return a+ac*(d2/(d2-d6));float va=d3*d6-d5*d4;if(va<=0&&d4-d3>=0&&d5-d6>=0)return b+(c-b)*((d4-d3)/(d4-d3+d5-d6));float den=1/(va+vb+vc);return a+ab*(vb*den)+ac*(vc*den);}
 public static async Task<string> Run(){var p=UnityEngine.Object.FindObjectsByType<MeshyNativeMotionPlayer>(FindObjectsInactive.Exclude).First(x=>x.GetComponent<WorkerAnt>().CurrentResourceNode!=null);var c=p.GetComponent<WorkerAnt>();var node=c.CurrentResourceNode;var visual=c.GetComponent<AntVisual>();AntColony.UI.SimulationPause.UserSpeed(0);p.PreviewMotion=p.PlayingMotion;var mount=p.GetComponentsInChildren<Transform>().First(t=>t.name=="Native equipment grip"&&t.gameObject.activeInHierarchy);var item=mount.GetChild(0);var verts=item.GetComponentsInChildren<MeshFilter>().SelectMany(f=>Read(f.sharedMesh).Select(v=>mount.InverseTransformPoint(f.transform.TransformPoint(v)))).ToArray();float low=verts.Min(v=>v.z),high=verts.Max(v=>v.z);var head=verts.Where(v=>v.z<low+(high-low)*.25f).ToArray();Vector3[] tips=visual.HeldTool.Contains("Axe")?new[]{head.OrderByDescending(v=>v.x).First()}:visual.HeldTool.Contains("Shovel")?new[]{head.OrderBy(v=>v.z).First()}:new[]{head.OrderBy(v=>v.x).First(),head.OrderByDescending(v=>v.x).First()};tips=tips.Select(v=>item.InverseTransformPoint(mount.TransformPoint(v))).ToArray();var surfaces=new List<(Vector3[],int[])>();foreach(var r in node.GetComponentsInChildren<MeshRenderer>()){if(!r.enabled||r.forceRenderingOff)continue;var f=r.GetComponent<MeshFilter>();if(!f)continue;surfaces.Add((Read(f.sharedMesh).Select(v=>f.transform.TransformPoint(v)).ToArray(),f.sharedMesh.triangles));}
 float best=float.MaxValue,phase=0;Vector3 bestTip=Vector3.zero,bestSurface=Vector3.zero;for(int i=0;i<96;i++){p.PreviewPhase=i/96f;await Task.Delay(30);foreach(var tip in tips){var point=item.TransformPoint(tip);foreach(var surface in surfaces){var vs=surface.Item1;var ids=surface.Item2;for(int j=0;j<ids.Length;j+=3){var q=Closest(point,vs[ids[j]],vs[ids[j+1]],vs[ids[j+2]]);float distance=(q-point).sqrMagnitude;if(distance<best){best=distance;phase=p.PreviewPhase;bestTip=point;bestSurface=q;}}}}}
 p.PreviewPhase=phase;await Task.Delay(100);var camera=Camera.main;UnityEngine.Object.FindAnyObjectByType<AntColony.Camera.IsometricCameraController>().enabled=false;var focus=(c.Position+node.transform.position)*.5f+Vector3.up*.4f;camera.orthographicSize=1.8f;camera.transform.position=focus+new Vector3(-3,2,-3);camera.transform.LookAt(focus);await Task.Delay(150);var name=node.ResourceType.ToString();ScreenCapture.CaptureScreenshot("work/final-motion-1113/contact-"+name+".png");await Task.Delay(200);var result=$"{name} cutting point nearest surface={Mathf.Sqrt(best):F4}m phase={phase:F4} point={bestTip:F3} surface={bestSurface:F3} actor={c.Position:F3}";File.WriteAllText("work/final-motion-1113/nearest-"+name+".txt",result);return result;}
}
